import{text,list,identifiers,choice}from'../creative-kit/state.js';
export const METHODS={need:'Remove the need',delivery:'Change the delivery',exposure:'Limit the exposure'};export const CONCERN_FIELDS=['objection','concern','evidence'];export const DESIGN_FIELDS=['title','mechanism','benefit','cost','test'];
export const concern=id=>({id,objection:'',concern:'',evidence:''});export const design=(id,method,concerns)=>({id,method,concerns,title:'An alternative to develop',mechanism:'',benefit:'',cost:'',test:'',stale:false});
export function make(id='first',example='example'){const w={id,problem:example==='blank'?'':'A rehearsal tool for unfamiliar battery decisions.',benefit:example==='blank'?'':'Let people practise a consequential choice before the real moment.',concerns:[],designs:[],selected:null};if(example!=='blank'){w.concerns=[{id:'c1',objection:'People will not make time for another training tool.',concern:'The learning benefit arrives later; the effort is needed now.',evidence:'Observe what prompts someone to practise without being told.'},{id:'c2',objection:'The simulation might create false confidence.',concern:'A simplified scenario may hide conditions that matter in operation.',evidence:'Ask users to explain the model’s limits after a rehearsal.'}];w.designs=[{...design('d1','delivery',['c1']),title:'Rehearsal at the point of change',mechanism:'Offer a five-minute scenario when a rule or operating condition changes.',benefit:'Practice stays tied to an imminent real choice.',cost:'Some users may still skip it when they are busy.',test:'Offer one scenario during a fictional rule change; observe voluntary completion.'}];}return w;}
export function validate(w){text(w.benefit);list(w.concerns,12);list(w.designs,18);identifiers(w.concerns);identifiers(w.designs);w.concerns.forEach(c=>CONCERN_FIELDS.forEach(f=>text(c[f])));for(const d of w.designs){choice(d.method,Object.keys(METHODS));DESIGN_FIELDS.forEach(f=>text(d[f]));list(d.concerns,12);if(!d.concerns.length||new Set(d.concerns).size!==d.concerns.length||d.concerns.some(id=>!w.concerns.some(c=>c.id===id)))throw Error('Each alternative needs an existing concern.');if(typeof d.stale!=='boolean')throw Error('Invalid review flag.');}if(w.selected!==null&&!w.designs.some(d=>d.id===w.selected))throw Error('Selected design is missing.');return w;}
export function apply(w,a){if(a.type==='edit'){if(a.collection==='workspace'){choice(a.field,['benefit']);w.benefit=text(a.value);w.designs.forEach(d=>d.stale=true);}else{const coll=choice(a.collection,['concerns','designs']),item=w[coll].find(i=>i.id===a.item);if(!item)throw Error('Item is missing.');choice(a.field,coll==='concerns'?CONCERN_FIELDS:DESIGN_FIELDS);item[a.field]=text(a.value);if(coll==='concerns')w.designs.filter(d=>d.concerns.includes(item.id)).forEach(d=>d.stale=true);}}else if(a.type==='add-concern')w.concerns.push(concern(a.id));else if(a.type==='fork'){if(!w.concerns.some(c=>c.id===a.concern))throw Error('Concern is missing.');choice(a.method,Object.keys(METHODS));w.designs.push(design(a.id,a.method,[a.concern]));}else if(a.type==='link'){const d=w.designs.find(d=>d.id===a.id);if(!d||!w.concerns.some(c=>c.id===a.concern))throw Error('Design or concern is missing.');if(!d.concerns.includes(a.concern)){d.concerns.push(a.concern);d.stale=true;}}else if(a.type==='remove-concern'){if(w.designs.some(d=>d.concerns.includes(a.id)))throw Error('This concern explains an alternative. Keep it while that design exists.');w.concerns=w.concerns.filter(c=>c.id!==a.id);}else if(a.type==='remove-design'){w.designs=w.designs.filter(d=>d.id!==a.id);if(w.selected===a.id)w.selected=null;}else if(a.type==='review'){const d=w.designs.find(d=>d.id===a.id);if(d)d.stale=false;}else if(a.type==='select'){if(!w.designs.some(d=>d.id===a.id))throw Error('Design is missing.');w.selected=a.id;}else throw Error('Unknown objections action.');}
export function markdown(w){return['# Objections into alternatives','',w.problem,'','## Original benefit',w.benefit,'',...w.concerns.flatMap(c=>[`## Objection: ${c.objection}`,'',`Underlying concern: ${c.concern}`,'',`Evidence or question: ${c.evidence}`,'']),...w.designs.flatMap(d=>[`## ${d.title}${w.selected===d.id?' · selected':''}${d.stale?' · context changed; recheck':''}`,`Method: ${METHODS[d.method]}`,`Addresses: ${d.concerns.map(id=>w.concerns.find(c=>c.id===id).objection).join('; ')}`,'',...DESIGN_FIELDS.slice(1).flatMap(f=>[`**${f}**`,d[f]||'_Not written._',''])])].join('\n');}
